void Solver::bump_var(int var, double coeff) {
    // Compute the increment once
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale all activities only when the current variable exceeds the safe bound.
    // This avoids the costly O(vars) loop on every bump.
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Update the VSIDS heap only if the variable is already present.
    // Skip the update for negligible increments to reduce heap churn.
    if (vsids.inHeap(var) && inc > 1e-12) {
        vsids.update(var);
    }
}
